function makePack({id,title,classId,subjectId,sourceUrl,sourceTitle,rows,kind='maths',band='primary'}){
 const weeks=rows.map(([topic,outcome,resources,starter,activity,task,check],index)=>({week:index+1,durationMinutes:kind==='integrated'?40:60,topic,
  strand:kind==='integrated'?'Integrated learning':topic.match(/data|chart|chance|probability|pictograph|mean/i)?'Data':topic.match(/shape|length|angle|area|volume|perimeter|mass|capacity|time|hours|circle|garden|pythagorean/i)?'Geometry and measurement':topic.match(/algebra|equation|factoris|pattern|linear|graph|bracket/i)?'Algebra':'Number',
  subStrand:topic,contentStandard:'',indicator:'',performanceIndicator:outcome,coreCompetencies:'Communication and collaboration; critical thinking and problem solving.',resources,keywords:topic.replaceAll(' and ', ', '),starter,
  mainActivity:kind==='integrated'?`${activity} Use short, supervised play episodes with movement breaks. Invite oral language, drawing and counting within the same theme. Support with picture choices and a familiar language; extend by asking the child to explain a choice or help plan the next step.`:`${activity} Model one example aloud, then give pairs time to practise and explain before individual work. Check a misconception using an incorrect example. ${band==='lower'?'Support with large concrete materials and fewer items; extend by inviting a new number story.':band==='jhs'?'Support with a diagram or partially worked example; extend by asking for a second method and the conditions under which it works.':'Support with a visual model or smaller values; extend by changing one condition and asking learners to justify the effect.'}`,
  assessment:`${task} Teacher check: ${check} ${kind==='integrated'?'Observe each child during play and record the level of prompting needed.':'Collect an individual explanation before peer checking and note the specific error for follow-up.'}`,
  plenary:kind==='integrated'?'Invite a child to show or tell one thing learned. Revisit a picture, song or model and plan a short follow-up from observations.':'Compare two explanations, agree on a reliable check, and ask each learner to name one next practice step.',reflection:''}));
 return {id,version:`edupal-content:${id}`,title,classId,subjectId,weekCount:12,sourceUrl,sourceTitle,reviewStatus:'Teacher review required',notice:`Original EduPalGh ${kind==='integrated'?'integrated learning':'Mathematics'} activities. Suggested 12-week unit; confirm coverage, level and sequencing against your school’s scheme. Not an official term schedule or a complete yearly course. Exact curriculum codes are left blank pending teacher verification.`,weeks};
}
